import React, { useEffect, useState } from 'react';
import { coursesAPI, testingAPI, activityAPI } from '../../api';

export default function StudentCoursesPage() {
  const [enrollments, setEnrollments] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [selectedModule, setSelectedModule] = useState(null);
  const [tests, setTests] = useState([]);
  const [testResult, setTestResult] = useState({ score: '', test: '' });
  const [myResults, setMyResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');
  const [msgType, setMsgType] = useState('success');
  const [view, setView] = useState('courses'); // courses | content | test

  const showMsg = (text, type = 'success') => {
    setMsg(text);
    setMsgType(type);
    setTimeout(() => setMsg(''), 3000);
  };

  useEffect(() => {
    Promise.all([
      coursesAPI.myCourses(),
      testingAPI.myResults(),
    ]).then(([e, r]) => {
      setEnrollments(e.data.results || e.data);
      setMyResults(r.data.results || r.data);
    }).finally(() => setLoading(false));
  }, []);

  const handleOpenModule = async (module, course) => {
    setSelectedModule(module);
    setSelectedCourse(course);
    setView('content');

    // Логируем просмотр модуля
    activityAPI.logEvent({
      course: course.id,
      module: module.id,
      action_type: 'view',
      session_start: new Date().toISOString(),
      session_end: new Date().toISOString(),
      duration_seconds: 0,
    }).catch(() => {});

    // Загружаем тесты модуля
    const { data } = await testingAPI.tests(module.id);
    setTests(data.results || data);
  };

  const handleSubmitTest = async (e, testId) => {
    e.preventDefault();
    try {
      await testingAPI.submitResult({
        test: testId,
        score: parseFloat(testResult.score),
        attempts: 1,
      });
      showMsg('Результат теста сохранён!');
      setTestResult({ score: '', test: '' });
      const { data } = await testingAPI.myResults();
      setMyResults(data.results || data);
    } catch {
      showMsg('Ошибка при сохранении результата', 'error');
    }
  };

  const getTestResult = (testId) => {
    return myResults.find(r => r.test === testId);
  };

  if (loading) return <div style={s.loading}>Загрузка курсов...</div>;

  return (
    <div>
      {/* Навигация */}
      <div style={s.breadcrumb}>
        <span style={s.breadcrumbLink} onClick={() => setView('courses')}>📚 Мои курсы</span>
        {selectedCourse && <><span style={s.breadcrumbSep}>›</span><span style={s.breadcrumbLink} onClick={() => setView('courses')}>{selectedCourse.course_title}</span></>}
        {selectedModule && <><span style={s.breadcrumbSep}>›</span><span style={s.breadcrumbCurrent}>{selectedModule.title}</span></>}
      </div>

      {msg && (
        <div style={{ ...s.msgBox, background: msgType === 'error' ? '#fee2e2' : '#dcfce7', color: msgType === 'error' ? '#991b1b' : '#166534' }}>
          {msg}
        </div>
      )}

      {/* Список курсов */}
      {view === 'courses' && (
        <div>
          <h1 style={s.h1}>📚 Мои курсы</h1>
          <p style={s.sub}>Выберите курс чтобы начать обучение</p>

          {enrollments.length === 0 ? (
            <div style={s.empty}>Вы ещё не записаны ни на один курс. Обратитесь к преподавателю.</div>
          ) : (
            enrollments.map(enrollment => (
              <div key={enrollment.id} style={s.courseCard}>
                <div style={s.courseHeader}>
                  <div>
                    <h2 style={s.courseTitle}>{enrollment.course_title}</h2>
                    <div style={s.progressWrap}>
                      <div style={s.progressBar}>
                        <div style={{ ...s.progressFill, width: `${enrollment.progress}%` }} />
                      </div>
                      <span style={s.progressText}>{enrollment.progress}% завершено</span>
                    </div>
                  </div>
                </div>

                {/* Модули курса */}
                <div style={s.modulesList}>
                  <div style={s.modulesTitle}>Модули:</div>
                  {enrollment.course_modules && enrollment.course_modules.length > 0 ? (
                    enrollment.course_modules.map((module, i) => (
                      <div key={module.id} style={s.moduleItem}
                        onClick={() => handleOpenModule(module, enrollment)}>
                        <span style={s.moduleNum}>{i + 1}</span>
                        <span style={s.moduleTitle}>{module.title}</span>
                        <span style={s.moduleArrow}>→</span>
                      </div>
                    ))
                  ) : (
                    <div style={s.noModules}>Модули ещё не добавлены преподавателем</div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Просмотр контента модуля */}
      {view === 'content' && selectedModule && (
        <div>
          <h1 style={s.h1}>{selectedModule.title}</h1>
          <p style={s.sub}>Курс: {selectedCourse?.course_title}</p>

          {/* Учебный контент */}
          <div style={s.contentCard}>
            <h3 style={s.sectionTitle}>📖 Учебный материал</h3>
            {selectedModule.content ? (
              <div style={s.contentText}>{selectedModule.content}</div>
            ) : (
              <div style={s.noContent}>Преподаватель ещё не добавил контент к этому модулю</div>
            )}
          </div>

          {/* Тесты модуля */}
          <div style={s.contentCard}>
            <h3 style={s.sectionTitle}>✏️ Тесты</h3>
            {tests.length === 0 ? (
              <div style={s.noContent}>Тестов для этого модуля пока нет</div>
            ) : (
              tests.map(test => {
                const result = getTestResult(test.id);
                return (
                  <div key={test.id} style={s.testCard}>
                    <div style={s.testHeader}>
                      <div>
                        <div style={s.testTitle}>{test.title}</div>
                        <div style={s.testMeta}>
                          Макс. балл: {test.max_score} | Проходной: {test.passing_score}
                        </div>
                      </div>
                      {result && (
                        <div style={{ ...s.resultBadge, background: result.passed ? '#dcfce7' : '#fee2e2', color: result.passed ? '#166534' : '#991b1b' }}>
                          {result.passed ? '✅ Пройден' : '❌ Не пройден'} — {result.score} баллов
                        </div>
                      )}
                    </div>

                    {!result && (
                      <form onSubmit={e => handleSubmitTest(e, test.id)} style={s.testForm}>
                        <div style={s.field}>
                          <label style={s.label}>Введите набранный балл</label>
                          <input
                            type="number"
                            style={{ ...s.input, maxWidth: 200 }}
                            min={0}
                            max={test.max_score}
                            value={testResult.test === test.id ? testResult.score : ''}
                            onChange={e => setTestResult({ test: test.id, score: e.target.value })}
                            placeholder={`0 — ${test.max_score}`}
                            required
                          />
                        </div>
                        <button type="submit" style={s.btnPrimary}>Сдать тест</button>
                      </form>
                    )}
                  </div>
                );
              })
            )}
          </div>

          <button style={s.btnSecondary} onClick={() => setView('courses')}>
            ← Вернуться к курсам
          </button>
        </div>
      )}
    </div>
  );
}

const s = {
  loading: { padding: 40, textAlign: 'center', color: '#64748b' },
  breadcrumb: { display: 'flex', alignItems: 'center', gap: 6, marginBottom: 20, fontSize: 14 },
  breadcrumbLink: { color: '#6366f1', cursor: 'pointer', fontWeight: 500 },
  breadcrumbSep: { color: '#94a3b8' },
  breadcrumbCurrent: { color: '#1e293b', fontWeight: 600 },
  h1: { fontSize: 28, fontWeight: 700, color: '#1e293b', margin: '0 0 4px' },
  sub: { color: '#64748b', marginBottom: 24 },
  msgBox: { padding: '12px 16px', borderRadius: 8, marginBottom: 16, fontSize: 14 },
  empty: { background: '#fff', borderRadius: 12, padding: 48, textAlign: 'center', color: '#94a3b8' },
  courseCard: { background: '#fff', borderRadius: 12, padding: 24, marginBottom: 16, boxShadow: '0 1px 4px rgba(0,0,0,0.08)' },
  courseHeader: { marginBottom: 16 },
  courseTitle: { fontSize: 20, fontWeight: 700, color: '#1e293b', margin: '0 0 12px' },
  progressWrap: { display: 'flex', alignItems: 'center', gap: 12 },
  progressBar: { flex: 1, maxWidth: 300, height: 8, background: '#f1f5f9', borderRadius: 4, overflow: 'hidden' },
  progressFill: { height: '100%', background: '#6366f1', borderRadius: 4 },
  progressText: { fontSize: 13, color: '#64748b', whiteSpace: 'nowrap' },
  modulesList: { borderTop: '1px solid #f1f5f9', paddingTop: 16 },
  modulesTitle: { fontSize: 12, fontWeight: 600, color: '#94a3b8', textTransform: 'uppercase', marginBottom: 8 },
  moduleItem: { display: 'flex', alignItems: 'center', gap: 12, padding: '10px 12px', borderRadius: 8, cursor: 'pointer', marginBottom: 4, transition: 'background 0.15s', background: '#f8fafc' },
  moduleNum: { width: 28, height: 28, background: '#6366f1', color: '#fff', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 700, flexShrink: 0 },
  moduleTitle: { flex: 1, fontSize: 14, fontWeight: 500, color: '#1e293b' },
  moduleArrow: { color: '#6366f1', fontWeight: 700 },
  noModules: { fontSize: 14, color: '#94a3b8', padding: '8px 0' },
  contentCard: { background: '#fff', borderRadius: 12, padding: 24, marginBottom: 16, boxShadow: '0 1px 4px rgba(0,0,0,0.08)' },
  sectionTitle: { fontSize: 16, fontWeight: 600, color: '#1e293b', margin: '0 0 16px' },
  contentText: { fontSize: 15, color: '#374151', lineHeight: 1.8, whiteSpace: 'pre-wrap' },
  noContent: { fontSize: 14, color: '#94a3b8', padding: '8px 0' },
  testCard: { background: '#f8fafc', borderRadius: 8, padding: 16, marginBottom: 12 },
  testHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 },
  testTitle: { fontSize: 15, fontWeight: 600, color: '#1e293b' },
  testMeta: { fontSize: 12, color: '#64748b', marginTop: 4 },
  resultBadge: { padding: '6px 14px', borderRadius: 8, fontSize: 13, fontWeight: 600 },
  testForm: { marginTop: 8 },
  field: { marginBottom: 12 },
  label: { display: 'block', fontSize: 13, fontWeight: 600, color: '#374151', marginBottom: 6 },
  input: { padding: '8px 12px', borderRadius: 8, border: '1.5px solid #d1d5db', fontSize: 14, width: '100%', boxSizing: 'border-box' },
  btnPrimary: { padding: '10px 20px', background: '#6366f1', color: '#fff', border: 'none', borderRadius: 8, fontSize: 14, fontWeight: 600, cursor: 'pointer' },
  btnSecondary: { padding: '10px 20px', background: '#f1f5f9', color: '#374151', border: 'none', borderRadius: 8, fontSize: 14, cursor: 'pointer', marginTop: 8 },
};
